<?php
require "config/database.php";require "includes/functions.php";
$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT j.*,c.name company_name,c.logo_color FROM jobs j JOIN companies c ON c.id=j.company_id WHERE j.id=?");$s->execute([$id]);$job=$s->fetch();
if(!$job){http_response_code(404);$pageTitle="Job not found";require "includes/header.php";echo '<section class="section container empty"><h2>Job not found</h2><a href="jobs.php">Browse jobs</a></section>';require "includes/footer.php";exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){require_login();$check=$pdo->prepare("SELECT id FROM applications WHERE job_id=? AND user_id=?");$check->execute([$id,$_SESSION['user']['id']]);if($check->fetch()){flash("You already applied for this job.","error");}else{$a=$pdo->prepare("INSERT INTO applications(job_id,user_id,cover_letter) VALUES(?,?,?)");$a->execute([$id,$_SESSION['user']['id'],trim($_POST['cover_letter']??'')]);flash("Your application has been submitted!");}header("Location: job-details.php?id=".$id);exit;}
$pageTitle=$job['title']." | Careerly";require "includes/header.php";
?>
<section class="page-hero"><div class="container"><a class="back" href="jobs.php">← Back to jobs</a><div class="detail-title"><div class="company-logo large" style="background:<?= e($job['logo_color']) ?>"><?= e(substr($job['company_name'],0,1)) ?></div><div><div class="eyebrow"><?= e($job['company_name']) ?></div><h1><?= e($job['title']) ?></h1><p><?= e($job['location']) ?> · <?= e($job['job_type']) ?> · <?= e($job['posted_label']) ?></p></div></div></div></section>
<section class="section"><div class="container detail-layout"><article class="prose"><h2>About the role</h2><p><?= nl2br(e($job['description'])) ?></p><h2>What we're looking for</h2><ul><?php foreach(explode("|",$job['requirements']) as $r): ?><li><?= e(trim($r)) ?></li><?php endforeach; ?></ul><h2>About the company</h2><p><?= e($job['company_name']) ?> is building products and experiences that help people do their best work.</p></article>
<aside class="apply-box"><div class="eyebrow">JOB OVERVIEW</div><?php foreach(["Salary"=>$job['salary'],"Job type"=>$job['job_type'],"Location"=>$job['location'],"Experience"=>$job['experience']] as $k=>$v): ?><div class="overview"><small><?= e($k) ?></small><b><?= e($v) ?></b></div><?php endforeach; ?>
<?php if(logged_in()): ?><form method="post"><label>Cover letter (optional)<textarea name="cover_letter" rows="4" placeholder="Why are you a good fit?"></textarea></label><button class="btn full">Apply for this job →</button></form><?php else: ?><a class="btn full" href="login.php">Log in to apply →</a><p class="tiny center">New here? <a href="register.php">Create an account</a></p><?php endif; ?></aside></div></section>
<?php require "includes/footer.php"; ?>
